"""Translations for figures, PDF report and HTML report (tr / en / de)."""

LANGS = ["tr", "en", "de"]

def fmt0(x, lang):
    s = f"{x:,.0f}"
    return s if lang == "en" else s.replace(",", ".")

def fmt1(x, lang):
    s = f"{x:,.1f}"
    if lang == "en": return s
    return s.replace(",", "X").replace(".", ",").replace("X", ".")

def fmt2(x, lang):
    s = f"{x:,.2f}"
    if lang == "en": return s
    return s.replace(",", "X").replace(".", ",").replace("X", ".")

